import{_ as t,o as a,c as o,m as s}from"./chunks/framework.Bsfm4Rg3.js";const g=JSON.parse('{"title":"Adoption Plan for Existing Applications","description":"","frontmatter":{},"headers":[],"relativePath":"guidance/adoption.md","filePath":"guidance/adoption.md"}'),r={name:"guidance/adoption.md"};function n(i,e,d,l,p,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adoption-plan-for-existing-applications" tabindex="-1">Adoption Plan for Existing Applications <a class="header-anchor" href="#adoption-plan-for-existing-applications" aria-label="Permalink to &quot;Adoption Plan for Existing Applications&quot;">​</a></h1><p>Cobalt is in alpha, and selected pilot groups are helping mature the design system. While component support, testing, and verification coverage expand, existing applications should adopt Cobalt in small, visible stages instead of planning a full UI replacement. This plan identifies a realistic adoption path for application teams that are not part of a pilot effort.</p><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>Use Cobalt in layers:</p><ol><li><strong>Tokens first.</strong> Adopt shared color, spacing, typography, radius, and focus decisions before replacing entire workflows.</li><li><strong>Baseline styles in scoped areas.</strong> Use <code>[data-co-base]</code> to progressively map native HTML elements to Cobalt typography and element defaults.</li><li><strong>Components only where ready.</strong> Replace components in small slices after checking docs, accessibility notes, wrappers, tests, and browser behavior.</li><li><strong>Roadmap the gaps.</strong> Keep local or legacy components where Cobalt does not yet support the pattern, and feed repeated blockers back into the roadmap.</li></ol><p>This mirrors patterns used by mature systems such as <a href="https://designsystem.digital.gov/maturity-model/" target="_blank" rel="noreferrer">USWDS</a>, <a href="https://atlassian.design/foundations/tokens/migrate-to-tokens/" target="_blank" rel="noreferrer">Atlassian</a>, <a href="https://carbondesignsystem.com/migrating/guide/overview/" target="_blank" rel="noreferrer">Carbon</a>, and <a href="https://polaris-react.shopify.com/version-guides/migrating-from-v11-to-v12" target="_blank" rel="noreferrer">Polaris</a>: adoption is incremental, measurable, and validated.</p><blockquote><p><strong>NOTE:</strong> Encountering blockers or questions during adoption? Use <a href="https://github.com/vizualization-lab/cobalt-design-system/issues/new/choose" target="_blank" rel="noreferrer">GitHub</a> to report bugs, request features, or ask for migration help. Your feedback is crucial for improving Cobalt and prioritizing roadmap items.</p></blockquote><h2 id="adoption-stages" tabindex="-1">Adoption Stages <a class="header-anchor" href="#adoption-stages" aria-label="Permalink to &quot;Adoption Stages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What changes</th><th>Progress signal</th><th>Exit criteria</th></tr></thead><tbody><tr><td>1. Choose a slice</td><td>Pick one route, workflow, or page region.</td><td>A small target surface is named.</td><td>Current UI stack, key elements, risks, and unsupported patterns are known.</td></tr><tr><td>2. Add tokens</td><td>Install tokens and replace hard-coded values where safe.</td><td>The slice uses Cobalt token imports and semantic <code>--co-*</code> values.</td><td>Import order is verified and key styles use tokens instead of raw values.</td></tr><tr><td>3. Add baseline styles</td><td>Scope <code>@cobalt/tokens/css/base</code> with <code>[data-co-base]</code>.</td><td>Native headings, text, links, lists, tables, and code align locally.</td><td>The scoped area passes visual review and does not regress adjacent UI.</td></tr><tr><td>4. Pilot ready components</td><td>Replace a few low-risk, documented components.</td><td>A real workflow uses Cobalt tokens, baseline styles, and components.</td><td>Visual, accessibility, framework, browser, and regression checks pass.</td></tr><tr><td>5. Make Cobalt the new-work default</td><td>Use Cobalt for new UI where support is ready.</td><td>New features start from Cobalt decisions instead of cleanup later.</td><td>Team standards define when to use Cobalt, defer, or file a roadmap gap.</td></tr><tr><td>6. Expand and retire legacy</td><td>Move repeated patterns as Cobalt support matures.</td><td>Legacy CSS or component dependencies decline by route, bundle, or app.</td><td>Migrated slices no longer depend on old UI systems except intentional gaps.</td></tr></tbody></table><h2 id="readiness-checks" tabindex="-1">Readiness Checks <a class="header-anchor" href="#readiness-checks" aria-label="Permalink to &quot;Readiness Checks&quot;">​</a></h2><p>Before expanding beyond a pilot, confirm:</p><ul><li>token CSS loads once and in the correct order</li><li>baseline styles are scoped and visually reviewed</li><li>selected components have usable docs and acceptable <a href="/cobalt-design-system/components/status.html">Component Status</a></li><li>wrapper behavior works in the app framework</li><li>keyboard, focus, accessibility, browser, theme, and regression checks pass</li><li>unsupported patterns have a local fallback and a roadmap issue when repeated</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/cobalt-design-system/guidance/element-mapping.html">Element Mapping</a></li><li><a href="/cobalt-design-system/guidance/migration.html">Migrating an Existing Application</a></li><li><a href="/cobalt-design-system/components/status.html">Component Status</a></li><li><a href="/cobalt-design-system/tokens/structure.html">Token Structure</a></li></ul>',14)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
